/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Sym, SymFunction, add, isUnsolved, parse, pprintUseUnicode, rational } from '../../src';
import { parseLatexLark } from '../../src/parsing';
import { at, pyStr, sympyMatches, sympyStr } from '../sympy-str';
import { equivalent } from '../sympy-equivalent';

describe("doctests of sympy.parsing.sympy_parser", () => {
  it("parse_expr(\"1*2=x\", transformations=(", () => {
    expect(sympyStr(parse('1*2=x', { convertEqualsSigns: true }))).toBe('Eq(2, x)');
  });
  it("parse_expr(\"(1*2=x)=False\", transformations=(", () => {
    expect(sympyStr(parse('(1*2=x)=False', { convertEqualsSigns: true }))).toBe('Eq(Eq(2, x), False)');
  });
  it("parse_expr('sin**4(x)', transformations=transformations)", () => {
    expect(sympyStr(parse('sin**4(x)', { transformations: ['functionExponentiation'] }))).toBe('sin(x)**4');
  });
  it("parse_expr('cot z + csc z', transformations=transformations)", () => {
    expect(sympyStr(parse('cot z + csc z', { transformations: ['implicitApplication'] }))).toBe('cot(z) + csc(z)');
  });
  it("parse_expr('3 x y', transformations=transformations)", () => {
    expect(sympyStr(parse('3 x y', { transformations: ['implicitMultiplication'] }))).toBe('3*x*y');
  });
  it("parse_expr(\"10sin**2 x**2 + 3xyz + tan theta\",", () => {
    expect(sympyStr(parse('10sin**2 x**2 + 3xyz + tan theta', { transformations: ['implicitMultiplication', 'implicitApplication', 'functionExponentiation', 'splitSymbols'] }))).toBe('3*x*y*z + 10*sin(x**2)**2 + tan(theta)');
  });
  it("parse_expr(\"1/2\")", () => {
    expect(sympyStr(parse('1/2', {}))).toBe('1/2');
  });
  it("parse_expr(\"2x\", transformations=transformations)", () => {
    expect(sympyStr(parse('2x', { transformations: ['implicitMultiplication', 'implicitApplication', 'functionExponentiation', 'splitSymbols'] }))).toBe('2*x');
  });
  it("a == b", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("a.args", () => {
    const x = new Sym('x');
    const v1 = x;
    expect(sympyStr([at(add(1, x).args, 0), v1], 't')).toBe('(1, x)');
  });
  it("b.args", () => {
    const x = new Sym('x');
    expect(sympyStr([x, rational(1)], 't')).toBe('(x, 1)');
  });
  it("parse_expr(\"2x\", transformations=T[:6])", () => {
    expect(sympyStr(parse('2x', { transformations: ['implicitMultiplication', 'implicitApplication', 'functionExponentiation', 'splitSymbols'] }))).toBe('2*x');
  });
  it("parse_expr('.3', transformations=T[3, 11])", () => {
    expect(equivalent(sympyStr(parse('.3', {})), '3/10', [], { fn: 'parse_expr', input: '\'.3\'' })).toBe(true);
  });
  it("parse_expr('.3x', transformations=T[:])", () => {
    expect(equivalent(sympyStr(parse('.3x', { transformations: ['implicitMultiplication', 'implicitApplication', 'functionExponentiation', 'splitSymbols'], convertEqualsSigns: true })), '3*x/10', [], { fn: 'parse_expr', input: '\'.3x\'' })).toBe(true);
  });
  it("parse_expr('.3x', transformations='all')", () => {
    expect(equivalent(sympyStr(parse('.3x', { transformations: 'all' })), '3*x/10', [], { fn: 'parse_expr', input: '\'.3x\'' })).toBe(true);
  });
  // no value
  //   parse_expr('unsplittable', transformations=standard_transformations +
  //   (transformation, implicit_multiplication))
  //   => unsplittable
  it.todo("parse_expr('unsplittable', transformations=standard_transformations +");
});

